def main(state, input_data):
    raw = state.get('bill_raw') or {}
    if not isinstance(raw, dict):
        raw = {}
    ex = raw.get('output')
    if ex is None:
        ex = raw.get('data')
    if not isinstance(ex, dict):
        ex = {}

    def num(v):
        try:
            if v is None or v == '':
                return None
            return float(v)
        except Exception:
            return None

    def near(a, b, tol):
        if a is None or b is None:
            return None
        base = abs(b) if abs(b) > 1 else 1.0
        return abs(a - b) <= max(2.0, base * tol)

    # ---- map universal schema -> the billing agent's `bill` contract ----
    lines = []
    for c in (ex.get('charges') or []):
        if not isinstance(c, dict):
            continue
        lines.append({'slab': c.get('slab_label'), 'units': num(c.get('units')), 'rate': num(c.get('rate')), 'amount': num(c.get('amount'))})
    energy = num(ex.get('energy_charges'))
    derived = []
    # A slab line read with units and rate but no amount (common on thermal print):
    # the amount is units x rate. If exactly one line is still blank and the energy
    # total was printed, that line is the remainder. Downstream forecasts sum these.
    blank = []
    for l in lines:
        if l['amount'] is None and l['units'] is not None and l['rate'] is not None:
            l['amount'] = round(l['units'] * l['rate'], 2)
            if 'slab_amount_via_rate' not in derived:
                derived.append('slab_amount_via_rate')
        if l['amount'] is None:
            blank.append(l)
    if len(blank) == 1 and energy is not None:
        known = 0.0
        for l in lines:
            if l['amount'] is not None:
                known = known + l['amount']
        rest = round(energy - known, 2)
        if rest >= 0:
            blank[0]['amount'] = rest
            derived.append('slab_amount_via_energy')
    line_sum = 0.0
    seen_line = False
    for l in lines:
        if l['amount'] is not None:
            line_sum = line_sum + l['amount']
            seen_line = True
    if energy is None and seen_line:
        energy = round(line_sum, 2)

    units_v = num(ex.get('units_consumed'))
    pres = num(ex.get('present_reading'))
    prev = num(ex.get('previous_reading'))
    # (1) OCR often drops the 'Units' line on thermal spot bills but keeps both meter
    #     readings -> units = present - previous. Only when that is a sane number.
    if units_v is None and pres is not None and prev is not None and pres >= prev and (pres - prev) < 20000:
        units_v = round(pres - prev)
        derived.append('units_via_readings')

    # (2) Total dropped but the component lines survived -> rebuild it. Flagged, and the
    #     gate still re-checks it against anything else the extraction found.
    total_v = num(ex.get('total_amount'))
    comp_keys = ('fixed_charges', 'customer_charges', 'electricity_duty', 'fuel_surcharge_fca', 'arrears', 'adjustments')
    if total_v is None and energy is not None:
        t = energy
        for k in comp_keys:
            kv = num(ex.get(k))
            if kv is not None:
                t = t + kv
        sv = num(ex.get('subsidy'))
        if sv is not None:
            t = t - abs(sv)
        total_v = round(t, 2)
        derived.append('total_via_components')

    # (3) Telangana spot bills print NO slab lines, only the energy total. Rebuild the
    #     telescopic slabs via the TG LT-I domestic tariff, and keep them ONLY if they
    #     reproduce the printed energy charge to within Rs 1 — never fabricated.
    dsc = str(ex.get('discom') or '').upper()
    stt = str(ex.get('state') or '').upper()
    is_tg = ('TGSPDCL' in dsc) or ('TSSPDCL' in dsc) or ('TGNPDCL' in dsc) or ('TSNPDCL' in dsc) or ('TELANGANA' in dsc) or ('TELANGANA' in stt)
    cat_u = str(ex.get('tariff_category') or '').upper()
    is_dom = ('DOM' in cat_u) or ('LT-I' in cat_u) or ('LT1' in cat_u) or ('1B' in cat_u) or (cat_u == '')
    if (not lines) and is_tg and is_dom and units_v is not None and energy is not None and units_v > 0:
        bands = [(100, [(50, 1.95), (50, 3.10)]), (200, [(100, 3.40), (100, 4.80)]), (1000000000, [(200, 5.10), (100, 7.70), (100, 9.00), (400, 9.50), (1000000000, 10.00)])]
        rebuilt = []
        for cap, slabs in bands:
            if units_v <= cap:
                left = units_v
                lo = 1
                for w, r in slabs:
                    take = w if left > w else left
                    if take <= 0:
                        break
                    rebuilt.append({'slab': str(int(lo)) + '-' + str(int(lo + take - 1)), 'units': take, 'rate': r, 'amount': round(take * r, 2)})
                    lo = lo + take
                    left = left - take
                break
        rsum = 0.0
        for x in rebuilt:
            rsum = rsum + x['amount']
        if rebuilt and abs(rsum - energy) <= 1.0:
            lines = rebuilt
            line_sum = rsum
            seen_line = True
            derived.append('slabs_via_tg_tariff')

    bill = {
        'consumer_name': ex.get('consumer_name'),
        'consumer_address': ex.get('consumer_address'),
        'service_number': ex.get('service_number'),
        'account_id': ex.get('account_id'),
        'meter_number': ex.get('meter_number'),
        'discom': ex.get('discom'),
        'state': ex.get('state'),
        'category': ex.get('tariff_category'),
        'connection_type': ex.get('connection_type'),
        'phase': ex.get('phase'),
        'sanctioned_load_kw': num(ex.get('sanctioned_load_kw')),
        'bill_number': ex.get('bill_number'),
        'billing_month': ex.get('billing_month'),
        'bill_date': ex.get('bill_date'),
        'due_date': ex.get('due_date'),
        'reading_date': ex.get('reading_date'),
        'previous_reading': prev,
        'present_reading': pres,
        'units_consumed': units_v,
        'charges': lines,
        'energy_charges': energy,
        'fixed_charges': num(ex.get('fixed_charges')),
        'customer_charges': num(ex.get('customer_charges')),
        'electricity_duty': num(ex.get('electricity_duty')),
        'fuel_surcharge_fca': num(ex.get('fuel_surcharge_fca')),
        'subsidy': num(ex.get('subsidy')),
        'arrears': num(ex.get('arrears')),
        'adjustments': num(ex.get('adjustments')),
        'total_amount': total_v,
        'amount_after_due_date': num(ex.get('amount_after_due_date')),
        'source_language': ex.get('source_language'),
    }

    # ---- validation gate: never let a silent guess through ----
    checks = []
    def chk(name, ok, sev, detail):
        checks.append({'check': name, 'ok': (True if ok else False), 'severity': sev, 'detail': detail})

    req_ok = bill['service_number'] not in (None, '') and bill['units_consumed'] is not None and bill['total_amount'] is not None
    chk('required_fields', req_ok, 'high', 'service_number, units_consumed, total_amount present')

    if seen_line and num(ex.get('energy_charges')) is not None:
        r = near(line_sum, energy, 0.03)
        chk('slab_sum_equals_energy', r, 'medium', 'sum of slab amounts ' + str(round(line_sum)) + ' vs energy charges ' + str(round(energy)))

    slab_bad = 0
    for l in lines:
        if l['units'] and l['rate'] and l['amount'] is not None:
            if not near(l['units'] * l['rate'], l['amount'], 0.05):
                slab_bad = slab_bad + 1
    if lines:
        chk('slab_units_x_rate', slab_bad == 0, 'medium', str(slab_bad) + ' slab line(s) where units x rate != amount')

    if bill['total_amount'] is not None and energy is not None:
        parts = energy
        for k in ('fixed_charges', 'customer_charges', 'electricity_duty', 'fuel_surcharge_fca', 'arrears', 'adjustments'):
            if bill[k] is not None:
                parts = parts + bill[k]
        sub = bill['subsidy'] or 0.0
        tot = bill['total_amount']
        ok_tot = near(parts - abs(sub), tot, 0.03) or near(parts + sub, tot, 0.03) or near(parts, tot, 0.03)
        chk('components_sum_to_total', ok_tot, 'medium', 'components ~' + str(round(parts)) + ' vs total ' + str(round(tot)))

    if bill['present_reading'] is not None and bill['previous_reading'] is not None and bill['units_consumed'] is not None:
        diff = bill['present_reading'] - bill['previous_reading']
        chk('reading_diff_equals_units', near(diff, bill['units_consumed'], 0.02), 'low', 'reading diff ' + str(round(diff)) + ' vs units ' + str(round(bill['units_consumed'])))

    conf = num(ex.get('extraction_confidence'))
    if conf is None:
        conf = 1.0
        for c in checks:
            if not c['ok']:
                conf = conf - (0.35 if c['severity'] == 'high' else 0.15 if c['severity'] == 'medium' else 0.05)
        if conf < 0:
            conf = 0.0
    else:
        for c in checks:
            if not c['ok'] and c['severity'] == 'high':
                conf = conf * 0.5
    conf = round(conf, 2)
    needs_review = (not req_ok) or conf < 0.6

    # drop nulls so downstream prompts stay clean (required keys always kept)
    clean = {}
    for k in bill:
        v = bill[k]
        if v is not None or k in ('service_number', 'units_consumed', 'total_amount', 'charges'):
            clean[k] = v

    # a derived total has nothing independent to check against -> always ask the citizen to confirm
    if 'total_via_components' in derived:
        needs_review = True

    return {
        'bill': clean,
        'valid': (True if raw.get('valid') else False),
        'needs_review': needs_review,
        'confidence': conf,
        'derived': derived,
        'checks': checks,
        'fields_found': raw.get('fields_found'),
        'ocr_used': (True if raw.get('ocr_used') else False),
        'template': raw.get('template'),
        'schema_errors': raw.get('errors') or [],
    }
